const products={honey:{name:'হানি নাট্টস',en:'Mini Honey Nuts',weight:20},mix:{name:'নাট্ট মিক্স',en:'Nut Mix',weight:18}};
export function unitPrice(q){return q>100?16:q>50?16.5:20}
const money=n=>'৳'+n.toLocaleString('en-US',{maximumFractionDigits:2});
let cart={};try{const saved=JSON.parse(localStorage.getItem('nutzora-bag-v1')||'{}');for(const id of Object.keys(products))if(Number.isInteger(saved[id])&&saved[id]>=10&&saved[id]<=10000)cart[id]=saved[id]}catch{}
const $=id=>document.getElementById(id);let previousFocus,toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function persist(){try{localStorage.setItem('nutzora-bag-v1',JSON.stringify(cart))}catch{}render()}
function render(){let count=0,total=0;const items=Object.entries(cart);$('cartItems').innerHTML=items.length?items.map(([id,q])=>{const p=products[id],price=unitPrice(q);count+=q;total+=q*price;return `<article class="cart-item"><div><h3>${p.name}</h3><small>${p.weight} গ্রাম · ${money(price)} / পিস · চামুচ ফ্রি</small><div class="item-qty"><button data-decrease="${id}" aria-label="${p.name} কমান" ${q<=10?'disabled':''}>−</button><input type="number" min="10" max="10000" step="1" value="${q}" data-qty="${id}" aria-label="${p.name} পিসের সংখ্যা"><button data-increase="${id}" aria-label="${p.name} বাড়ান">+</button><button class="remove-item" data-remove="${id}">সরান</button></div></div><strong class="item-total">${money(q*price)}</strong></article>`}).join(''):'<div class="empty-cart"><b>♧</b>আপনার ব্যাগ এখন খালি।<br>পছন্দের পণ্য দিয়ে শুরু করুন।</div>';$('cartCount').textContent=count;$('cartTotal').textContent=money(total);$('checkout').disabled=!items.length}
function setCart(open){const d=$('cartDrawer');if(open){previousFocus=document.activeElement;$('overlay').hidden=false;d.inert=false;d.classList.add('open');document.body.style.overflow='hidden';$('cartClose').focus()}else{d.classList.remove('open');d.inert=true;$('overlay').hidden=true;document.body.style.overflow='';previousFocus?.focus()}}
function add(id,quantity=10){cart[id]=Math.min(10000,(cart[id]||0)+quantity);persist();toast(products[id].name+' — '+quantity+' পিস ব্যাগে রাখা হয়েছে');}
$('cartOpen').addEventListener('click',()=>setCart(true));$('cartClose').addEventListener('click',()=>setCart(false));$('overlay').addEventListener('click',()=>setCart(false));
document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>add(b.dataset.add)));
$('cartItems').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let id;if(id=b.dataset.decrease)cart[id]=Math.max(10,cart[id]-1);if(id=b.dataset.increase)cart[id]=Math.min(10000,cart[id]+1);if(id=b.dataset.remove)delete cart[id];persist()});
$('cartItems').addEventListener('change',e=>{const id=e.target.dataset.qty;if(!id)return;const q=Math.round(Number(e.target.value));if(!Number.isFinite(q)||q<10||q>10000)toast('পরিমাণ ১০ থেকে ১০,০০০ পিসের মধ্যে দিন');cart[id]=Math.min(10000,Math.max(10,q||10));persist()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')setCart(false);if(e.key==='Tab'&&$('cartDrawer').classList.contains('open')){const els=[...$('cartDrawer').querySelectorAll('button:not(:disabled),input,textarea,a')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('checkout').addEventListener('click',()=>{let total=0;const lines=Object.entries(cart).map(([id,q])=>{let p=products[id],line=q*unitPrice(q);total+=line;return `${p.name} (${p.weight}g): ${q} পিস × ৳${unitPrice(q)} = ৳${line}`});if(!lines.length)return;const note=$('orderNote').value.trim().slice(0,1000);const text=`আসসালামু আলাইকুম, SA-BR Nutzora!\nঅর্ডার করতে চাই:\n\n${lines.join('\n')}\n\nপণ্যের মোট মূল্য: ৳${total}\nপ্রতি বক্সে ১টি চামুচ ফ্রি।\nডেলিভারি চার্জ ও অর্ডার নিশ্চিত করবেন।${note?'\nনোট: '+note:''}`;window.open('https://wa.me/8801613141834?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')});
let selected='honey';function detail(id){if(!products[id])return;selected=id;$('detailPhoto').hidden=id!=='honey';$('detailEdit').textContent=products[id].en.toUpperCase();$('detailName').textContent=products[id].name;$('detailWeight').textContent=products[id].weight+' গ্রাম · ছোট স্বচ্ছ বক্স';if(!$('productDialog').open)$('productDialog').showModal()}
document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>detail(b.dataset.product)));window.addEventListener('nutzora-product',e=>detail(e.detail));$('productClose').addEventListener('click',()=>$('productDialog').close());$('productDialog').addEventListener('click',e=>{if(e.target===$('productDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('detailAdd').addEventListener('click',()=>{add(selected);$('productDialog').close()});
// Independent, lightweight card perspective treatment inspired by Aceternity's 3D Card Effect.
for(const el of document.querySelectorAll('[data-tilt]')){el.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(1400px) rotateY(${x*3}deg) rotateX(${-y*3}deg)`});el.addEventListener('pointerleave',()=>el.style.transform='')}
render();

// Page-level shopping interactions and progressive animation.
const pageName=location.pathname.split('/').pop()||'index.html';
for(const link of document.querySelectorAll('nav a'))if(link.getAttribute('href')===pageName)link.setAttribute('aria-current','page');
$('menuToggle').addEventListener('click',()=>{const expanded=$('menuToggle').getAttribute('aria-expanded')==='true';$('menuToggle').setAttribute('aria-expanded',String(!expanded));$('mobileMenu').hidden=expanded;$('menuToggle').textContent=expanded?'☰':'×'});
if('IntersectionObserver' in window){document.documentElement.classList.add('js-reveal');const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}},{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}
function progress(){const max=document.documentElement.scrollHeight-innerHeight;$('pageProgress').style.transform='scaleX('+(max>0?scrollY/max:0)+')'}window.addEventListener('scroll',progress,{passive:true});progress();
const qty=$('productQty');function normalizeQty(){return Math.max(10,Math.min(10000,Math.round(Number(qty.value))||10))}function updateQty(){const q=normalizeQty();qty.value=q;$('unitAmount').textContent=money(unitPrice(q));$('quantityTotal').textContent=money(q*unitPrice(q))}
if(qty){qty.addEventListener('input',()=>{const q=normalizeQty();$('unitAmount').textContent=money(unitPrice(q));$('quantityTotal').textContent=money(q*unitPrice(q))});qty.addEventListener('blur',updateQty);qty.addEventListener('change',updateQty);$('qtyLess').addEventListener('click',()=>{qty.value=normalizeQty()-1;updateQty()});$('qtyMore').addEventListener('click',()=>{qty.value=normalizeQty()+1;updateQty()});$('productOrder').addEventListener('click',()=>{updateQty();add($('productOrder').dataset.id,normalizeQty());setCart(true)});updateQty()}
for(const thumb of document.querySelectorAll('[data-image]'))thumb.addEventListener('click',()=>{const main=$('galleryMain');main.src=thumb.dataset.image;main.alt=thumb.querySelector('img').alt;main.animate([{opacity:.3,transform:'scale(.985)'},{opacity:1,transform:'scale(1)'}],{duration:400,easing:'ease-out'})});
let activeFilter='all';function filterProducts(){let shown=0;const query=($('productSearch')?.value||'').trim().toLocaleLowerCase();for(const card of document.querySelectorAll('.shop-section .product-card')){const match=(activeFilter==='all'||card.dataset.kind===activeFilter)&&card.textContent.toLocaleLowerCase().includes(query);card.hidden=!match;if(match)shown++}if($('noResults'))$('noResults').hidden=shown>0}
for(const filter of document.querySelectorAll('[data-filter]'))filter.addEventListener('click',()=>{activeFilter=filter.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===filter));filterProducts()});$('productSearch')?.addEventListener('input',filterProducts);
window.addEventListener('pageshow',()=>document.body.classList.remove('leaving'));
